    /// <summary>Two floats as an fp16x2 word (lo in the low half).</summary>
    private static uint Tc2Pack(float lo, float hi)
    {
        CudaAsm.Emit("cvt.rn.f16x2.f32 %0, %1, %2;", out uint packed, hi, lo);
        return packed;
    }

    /// <summary>
    /// Activations for <see cref="TcGemm2{T}"/>: xh[t, c] = (half)clamp(x[XOff + t·XStride + c]), four columns per thread,
    /// once per GEMM instead of once per weight-row block.
    /// </summary>
    public static void ToHalfRows(Index1D i, ArrayView<float> x, ArrayView<Half> xh, long xOff, int xStride, int cols)
    {
        int c4 = cols / 4, t = (int)(i / c4), c = (int)(i - (long)t * c4) * 4;
        Float4 v = x.Cast<Float4>()[(xOff + (long)t * xStride + c) / 4];
        var h2 = xh.Cast<uint>();
        long o = ((long)t * cols + c) / 2;
        h2[o] = Tc2Pack(Clamp16(v.X), Clamp16(v.Y));
        h2[o + 1] = Tc2Pack(Clamp16(v.Z), Clamp16(v.W));
    }

    /// <summary>
    /// <see cref="ToHalfRows"/> of the activations rounded as <see cref="QuantizeQ8"/> rounds them (q·d per block of 32,
    /// d = max|x| / 127): prompt GEMMs then see the values the int8 decode kernels see, so a prefix computed in a prompt
    /// and one computed while decoding agree as closely as they did in float. cols is a multiple of 256 (whole warps).
    /// </summary>
    public static void ToHalfRowsQ8(Index1D i, ArrayView<float> x, ArrayView<Half> xh, long xOff, int xStride, int cols)
    {
        int c4 = cols / 4, t = (int)(i / c4), c = (int)(i - (long)t * c4) * 4;
        Float4 v = x.Cast<Float4>()[(xOff + (long)t * xStride + c) / 4];
        float amax = MathF.Max(MathF.Max(MathF.Abs(v.X), MathF.Abs(v.Y)), MathF.Max(MathF.Abs(v.Z), MathF.Abs(v.W)));
        amax = MathF.Max(amax, ILGPU.Warp.ShuffleXor(amax, 1));
        amax = MathF.Max(amax, ILGPU.Warp.ShuffleXor(amax, 2));
        amax = MathF.Max(amax, ILGPU.Warp.ShuffleXor(amax, 4));
        float d = amax / 127f, inv = amax > 0 ? 127f / amax : 0f;
        var h2 = xh.Cast<uint>();
        long o = ((long)t * cols + c) / 2;
        h2[o] = Tc2Pack(MathF.Round(v.X * inv) * d, MathF.Round(v.Y * inv) * d);
        h2[o + 1] = Tc2Pack(MathF.Round(v.Z * inv) * d, MathF.Round(v.W * inv) * d);
    }
